   1→using System.Collections.ObjectModel;
   2→using Six.Automerge;
   3→using Six.Automerge.Repository.Network;
   4→using Six.Automerge.Repository.Storage;
   5→using Six.Automerge.Repository.Synchronizer;
   6→
   7→namespace Six.Automerge.Repository;
   8→
   9→/// <summary>
  10→/// Central repository for managing Automerge documents with persistence and sync.
  11→/// </summary>
  12→/// <remarks>
  13→/// <para>
  14→/// The Repo is the main entry point of this library. To construct a Repo you will need
  15→/// an IStorageAdapter and one or more INetworkAdapters. Once you have a Repo you can
  16→/// use it to obtain DocHandles.
  17→/// </para>
  18→/// <para>
  19→/// This is a C# port of the TypeScript automerge-repo Repo class, maintaining API compatibility.
  20→/// </para>
  21→/// </remarks>
  22→[PublicAPI]
  23→public sealed class Repo : IDisposable
  24→{
  25→  // Subsystems
  26→  readonly StorageSubsystem? _storage;
  27→  readonly NetworkSubsystem _network;
  28→  readonly CollectionSynchronizer _synchronizer;
  29→
  30→  // Configuration
  31→  readonly PeerId _peerId;
  32→  readonly bool _isEphemeral;
  33→  readonly int _saveDebounceRate;
  34→  readonly ShareConfig _shareConfig;
  35→  readonly Func<IReadOnlyList<string>, Task<byte[]>>? _idFactory;
  36→
  37→  // Handle management
  38→  readonly Dictionary<string, IDocHandle> _handleCache = [];
  39→  readonly Dictionary<string, Task<IDocHandle>> _findInProgress = [];
  40→  readonly SemaphoreSlim _handleLock = new(1, 1);
  41→
  42→  // Save throttling
  43→  readonly Dictionary<string, CancellationTokenSource> _pendingSaves = [];
  44→  readonly SemaphoreSlim _saveLock = new(1, 1);
  45→
  46→  bool _isDisposed;
  47→
  48→
  49→  #region Events
  50→
  51→  /// <summary>
  52→  /// Raised when a document is loaded and ready.
  53→  /// </summary>
  54→  public event EventHandler<DocumentEventArgs>? DocumentLoaded;
  55→
  56→  /// <summary>
  57→  /// Raised when a document is deleted.
  58→  /// </summary>
  59→  public event EventHandler<DocumentDeletedEventArgs>? DocumentDeleted;
  60→
  61→  /// <summary>
  62→  /// Raised when a document is unavailable from all peers.
  63→  /// </summary>
  64→  public event EventHandler<DocumentUnavailableEventArgs>? DocumentUnavailable;
  65→
  66→  /// <summary>
  67→  /// Raised when a peer connects.
  68→  /// </summary>
  69→  public event EventHandler<PeerEventArgs>? PeerConnected;
  70→
  71→  /// <summary>
  72→  /// Raised when a peer disconnects.
  73→  /// </summary>
  74→  public event EventHandler<PeerEventArgs>? PeerDisconnected;
  75→
  76→  #endregion
  77→
  78→  #region Properties
  79→
  80→  /// <summary>
  81→  /// Gets the peer ID of this repository.
  82→  /// </summary>
  83→  public PeerId PeerId => _peerId;
  84→
  85→  /// <summary>
  86→  /// Gets the list of currently connected peers.
  87→  /// </summary>
  88→  public IReadOnlyList<PeerId> Peers => _network.Peers;
  89→
  90→  /// <summary>
  91→  /// Gets a read-only snapshot of all cached handles.
  92→  /// </summary>
  93→  public async Task<IReadOnlyDictionary<string, IDocHandle>> GetHandlesAsync()
  94→  {
  95→    await _handleLock.WaitAsync().ConfigureAwait(false);
  96→    try
  97→    {
  98→      return new ReadOnlyDictionary<string, IDocHandle>(
  99→        new Dictionary<string, IDocHandle>(_handleCache));
 100→    }
 101→    finally
 102→    {
 103→      _handleLock.Release();
 104→    }
 105→  }
 106→
 107→  #endregion
 108→
 109→
 110→  /// <summary>
 111→  /// Initializes a new repository with the specified configuration.
 112→  /// </summary>
 113→  /// <param name="config">Configuration for the repository.</param>
 114→  /// <exception cref="ArgumentNullException">Thrown if config is null.</exception>
 115→  public Repo(RepoConfig config)
 116→  {
 117→    if(config is null)
 118→      throw new ArgumentNullException(nameof(config));
 119→
 120→    // Initialize identity
 121→    _peerId = config.PeerId ?? PeerId.Generate();
 122→    _isEphemeral = config.IsEphemeral;
 123→    _saveDebounceRate = config.SaveDebounceRate;
 124→    _shareConfig = config.ShareConfig ?? ShareConfig.AllowAll;
 125→    _idFactory = config.IdFactory;
 126→
 127→    // Initialize storage subsystem
 128→    if(config.Storage is not null)
 129→    {
 130→      _storage = new StorageSubsystem(config.Storage);
 131→      _storage.DocumentLoaded += OnStorageDocumentLoaded;
 132→      _storage.DocumentSaved += OnStorageDocumentSaved;
 133→    }
 134→
 135→    // Initialize network subsystem
 136→    _network = new NetworkSubsystem(config.NetworkAdapters);
 137→    _network.PeerCandidate += OnNetworkPeerCandidate;
 138→    _network.PeerDisconnected += OnNetworkPeerDisconnected;
 139→    _network.MessageReceived += OnNetworkMessageReceived;
 140→
 141→    // Initialize synchronizer
 142→    _synchronizer = new CollectionSynchronizer(
 143→      GetDocument,
 144→      UpdateDocument,
 145→      GetPeerMetadata,
 146→      RequestDocument,
 147→      GetDocumentLock,
 148→      config.Denylist);
 149→
 150→    _synchronizer.MessageToSend += OnSynchronizerMessage;
 151→    _synchronizer.SyncStateChanged += OnSynchronizerSyncStateChanged;
 152→    _synchronizer.DocumentUnavailable += OnSynchronizerDocumentUnavailable;
 153→
 154→    // Set share and access policies
 155→    if(_shareConfig.Announce is not null)
 156→    {
 157→      _synchronizer.SetSharePolicy(AdaptAnnouncePolicy);
 158→    }
 159→
 160→    if(_shareConfig.Access is not null)
 161→    {
 162→      _synchronizer.SetAccessPolicy(AdaptAccessPolicy);
 163→    }
 164→  }
 165→
 166→
 167→  /// <summary>
 168→  /// Disposes the repository and releases all resources.
 169→  /// </summary>
 170→  public void Dispose()
 171→  {
 172→    if(_isDisposed) return;
 173→
 174→    _isDisposed = true;
 175→
 176→    // Cancel all pending saves
 177→    _saveLock.Wait();
 178→    try
 179→    {
 180→      foreach(var cts in _pendingSaves.Values)
 181→      {
 182→        cts.Cancel();
 183→        cts.Dispose();
 184→      }
 185→
 186→      _pendingSaves.Clear();
 187→    }
 188→    finally
 189→    {
 190→      _saveLock.Release();
 191→    }
 192→
 193→    // Dispose synchronizer
 194→    _synchronizer.Dispose();
 195→
 196→    // Dispose network subsystem
 197→    _network.Dispose();
 198→
 199→    // Dispose storage subsystem
 200→    _storage?.Dispose();
 201→
 202→    // Dispose all handles
 203→
 204→    _handleLock.Wait();
 205→    try
 206→    {
 207→      foreach(var handle in _handleCache.Values)
 208→      {
 209→        handle.Dispose();
 210→      }
 211→
 212→      _handleCache.Clear();
 213→    }
 214→    finally
 215→    {
 216→      _handleLock.Release();
 217→    }
 218→
 219→    // Dispose locks
 220→    _handleLock.Dispose();
 221→    _saveLock.Dispose();
 222→  }
