 228→  // Policy adapter: Announce(peerId, docId?) → SharePolicy(docId, peerId)
 229→  async Task<bool> AdaptAnnouncePolicy(DocumentId documentId, PeerId peerId)
 230→  {
 231→    if(_shareConfig.Announce is null) return true;
 232→    return await _shareConfig.Announce(peerId, documentId).ConfigureAwait(false);
 233→  }
 234→
 235→  // Policy adapter: Access(peerId, docId) → AccessPolicy(docId, peerId)
 236→  async Task<bool> AdaptAccessPolicy(DocumentId documentId, PeerId peerId)
 237→  {
 238→    if(_shareConfig.Access is null) return true;
 239→    return await _shareConfig.Access(peerId, documentId).ConfigureAwait(false);
 240→  }
