 242→
 243→  #region Document Lifecycle - Create
 244→
 245→  /// <summary>
 246→  /// Creates a new document with optional initial value.
 247→  /// Uses default document ID generation (not the idFactory).
 248→  /// For custom ID generation via idFactory, use CreateAsync{T}().
 249→  /// </summary>
 250→  /// <typeparam name="T">The document content type.</typeparam>
 251→  /// <param name="initialValue">Optional initial value for the document.</param>
 252→  /// <returns>A task that resolves to a handle to the newly created document.</returns>
 253→  public async Task<DocHandle<T>> Create<T>(T? initialValue = default)
 254→  {
 255→    ThrowIfDisposed();
 256→
 257→    // Generate document ID using default generator (not idFactory)
 258→    // idFactory is async, so it's handled in CreateAsync() instead
 259→    var documentId = DocumentId.Generate();
 260→
 261→    // Validate document ID
 262→    if(!DocumentId.IsValid(documentId))
 263→    {
 264→      throw new ArgumentException($"Invalid document ID: {documentId}");
 265→    }
 266→
 267→    DocHandle<T> handle;
 268→
 269→    await _handleLock.WaitAsync().ConfigureAwait(false);
 270→    try
 271→    {
 272→      // Check if already exists
 273→      if(_handleCache.ContainsKey(documentId))
 274→      {
 275→        throw new InvalidOperationException($"Document already exists: {documentId}");
 276→      }
 277→
 278→      // Create document
 279→      var doc = AutomergeDocument.Create();
 280→
 281→      // Create handle
 282→      handle = new DocHandle<T>(
 283→        documentId,
 284→        new DocHandleOptions<T> { IsNew = true, ViewFactory = CreateViewFactory<T>() },
 285→        doc);
 286→
 287→      // Cache handle
 288→      _handleCache[documentId] = handle;
 289→    }
 290→    finally
 291→    {
 292→      _handleLock.Release();
 293→    }
 294→
 295→    // Register outside the lock to prevent deadlocks
 296→    // (RegisterHandle → synchronizer.AddDocument → docSync.BeginSync → GetDocument callback → _handleLock)
 297→    await RegisterHandle(documentId, handle).ConfigureAwait(false);
 298→
 299→    // Emit event
 300→    DocumentLoaded?.Invoke(this,
 301→      new DocumentEventArgs { DocumentId = documentId, Handle = handle });
 302→
 303→    return handle;
 304→  }
 305→
 306→  /// <summary>
 307→  /// Creates a new document asynchronously with optional initial value.
 308→  /// Uses idFactory for document ID generation if configured.
 309→  /// This mirrors TypeScript's experimental Repo.create2() method.
 310→  /// </summary>
 311→  /// <typeparam name="T">The document content type.</typeparam>
 312→  /// <param name="initialValue">Optional initial value for the document.</param>
 313→  /// <returns>A task that resolves to a handle to the newly created document.</returns>
 314→  public async Task<DocHandle<T>> CreateAsync<T>(T? initialValue = default)
 315→  {
 316→    ThrowIfDisposed();
 317→
 318→    // Generate document ID
 319→    DocumentId documentId;
 320→    if(_idFactory is not null)
 321→    {
 322→      // Use idFactory for ID generation
 323→      var initialDoc = AutomergeDocument.Create();
 324→      var heads = initialDoc.GetHeads();
 325→      var binaryId = await _idFactory(heads).ConfigureAwait(false);
 326→      documentId = DocumentId.FromBinary(binaryId);
 327→    }
 328→    else
 329→    {
 330→      // Fall back to default ID generation
 331→      documentId = DocumentId.Generate();
 332→    }
 333→
 334→    // Validate document ID
 335→    if(!DocumentId.IsValid(documentId))
 336→    {
 337→      throw new ArgumentException($"Invalid document ID: {documentId}");
 338→    }
 339→
 340→    DocHandle<T> handle;
 341→
 342→    await _handleLock.WaitAsync().ConfigureAwait(false);
 343→    try
 344→    {
 345→      // Check if already exists
 346→      if(_handleCache.ContainsKey(documentId))
 347→      {
 348→        throw new InvalidOperationException($"Document already exists: {documentId}");
 349→      }
 350→
 351→      // Create document
 352→      var doc = AutomergeDocument.Create();
 353→
 354→      // Create handle
 355→      handle = new DocHandle<T>(
 356→        documentId,
 357→        new DocHandleOptions<T> { IsNew = true, ViewFactory = CreateViewFactory<T>() },
 358→        doc);
 359→
 360→      // Cache handle
 361→      _handleCache[documentId] = handle;
 362→    }
 363→    finally
 364→    {
 365→      _handleLock.Release();
 366→    }
 367→
 368→    // Register outside the lock to prevent deadlocks
 369→    await RegisterHandle(documentId, handle).ConfigureAwait(false);
 370→
 371→    // Emit event
 372→    DocumentLoaded?.Invoke(this,
 373→      new DocumentEventArgs { DocumentId = documentId, Handle = handle });
 374→
 375→    return handle;
 376→  }
