 378→  /// <summary>
 379→  /// Creates a new document with a specific document ID and optional initial value.
 380→  /// </summary>
 381→  /// <typeparam name="T">The document content type.</typeparam>
 382→  /// <param name="documentId">The document ID to use for the new document.</param>
 383→  /// <param name="initialValue">Optional initial value for the document.</param>
 384→  /// <returns>A task that resolves to a handle to the newly created document.</returns>
 385→  /// <exception cref="ArgumentException">Thrown if document ID is invalid.</exception>
 386→  /// <exception cref="InvalidOperationException">Thrown if a document with this ID already exists.</exception>
 387→  public async Task<DocHandle<T>> Create<T>(string documentId, T? initialValue = default)
 388→  {
 389→    ThrowIfDisposed();
 390→
 391→    if(string.IsNullOrWhiteSpace(documentId))
 392→      throw new ArgumentException("Document ID cannot be null or whitespace", nameof(documentId));
 393→
 394→    // Validate document ID
 395→    if(!DocumentId.IsValid(documentId))
 396→    {
 397→      throw new ArgumentException($"Invalid document ID: {documentId}");
 398→    }
 399→
 400→    var documentIdValue = DocumentId.Parse(documentId);
 401→
 402→    DocHandle<T> handle;
 403→
 404→    await _handleLock.WaitAsync().ConfigureAwait(false);
 405→    try
 406→    {
 407→      // Check if already exists
 408→      if(_handleCache.ContainsKey(documentId))
 409→      {
 410→        throw new InvalidOperationException($"Document already exists: {documentId}");
 411→      }
 412→
 413→      // Create document
 414→      var doc = AutomergeDocument.Create();
 415→
 416→      // Create handle
 417→      handle = new DocHandle<T>(
 418→        documentId,
 419→        new DocHandleOptions<T> { IsNew = true, ViewFactory = CreateViewFactory<T>() },
 420→        doc);
 421→
 422→      // Cache handle
 423→      _handleCache[documentId] = handle;
 424→    }
 425→    finally
 426→    {
 427→      _handleLock.Release();
 428→    }
 429→
 430→    // Register outside the lock to prevent deadlocks
 431→    await RegisterHandle(documentId, handle).ConfigureAwait(false);
 432→
 433→    // Emit event
 434→    DocumentLoaded?.Invoke(this,
 435→      new DocumentEventArgs { DocumentId = documentIdValue, Handle = handle });
 436→
 437→    return handle;
 438→  }
 439→
 440→  #endregion
 441→
 442→  #region Document Lifecycle - Find
 443→
 444→  /// <summary>
 445→  /// Finds an existing document, loading from storage or requesting from network.
 446→  /// </summary>
 447→  /// <typeparam name="T">The document content type.</typeparam>
 448→  /// <param name="documentId">The document ID to find.</param>
 449→  /// <param name="timeout">Optional timeout for loading. Default: 10 seconds.</param>
 450→  /// <returns>
 451→  /// A <see cref="DocHandle{T}"/> if the document exists or was loaded successfully, or null if the document
 452→  /// does not exist and could not be loaded from the network within the timeout period.
 453→  /// </returns>
 454→  /// <exception cref="ArgumentException">Thrown if document ID is invalid.</exception>
 455→  public async Task<DocHandle<T>?> Find<T>(string documentId, TimeSpan? timeout = null)
 456→  {
 457→    if(string.IsNullOrWhiteSpace(documentId))
 458→      throw new ArgumentException("Document ID cannot be null or whitespace", nameof(documentId));
 459→
 460→    if(!DocumentId.IsValid(documentId))
 461→      throw new ArgumentException($"Invalid document ID: {documentId}", nameof(documentId));
 462→
 463→    var documentIdValue = DocumentId.Parse(documentId);
 464→
 465→    ThrowIfDisposed();
 466→
 467→    timeout ??= TimeSpan.FromSeconds(10);
 468→
 469→    await _handleLock.WaitAsync().ConfigureAwait(false);
 470→    Task<IDocHandle>? findTask;
 471→    try
 472→    {
 473→      // Check cache first
 474→      if(_handleCache.TryGetValue(documentId, out var cachedHandle))
 475→      {
 476→        return (DocHandle<T>)cachedHandle;
 477→      }
 478→
 479→      // Check if find already in progress
 480→      if(_findInProgress.TryGetValue(documentId, out findTask))
 481→      {
 482→        // Wait for existing find operation
 483→        _handleLock.Release();
 484→        var result = await findTask.ConfigureAwait(false);
 485→        return (DocHandle<T>)result;
 486→      }
 487→
 488→      // Start new find operation
 489→      var tcs = new TaskCompletionSource<IDocHandle>();
 490→      _findInProgress[documentId] = tcs.Task;
 491→      findTask = tcs.Task;
 492→    }
 493→    finally
 494→    {
 495→      if(_handleLock.CurrentCount == 0)
 496→        _handleLock.Release();
 497→    }
 498→
 499→    try
 500→    {
 501→      // Attempt to load from storage first
 502→      AutomergeDocument? doc = null;
 503→      if(_storage is not null)
 504→      {
 505→        doc = await _storage.LoadDoc(documentId).ConfigureAwait(false);
 506→      }
 507→
 508→      // Create handle (without document - we'll initialize explicitly)
 509→      var handle = new DocHandle<T>(
 510→        documentId,
 511→        new DocHandleOptions<T> { IsNew = false, ViewFactory = CreateViewFactory<T>(), Timeout = timeout.Value },
 512→        document: null);
 513→
 514→      // Cache handle
 515→      await _handleLock.WaitAsync().ConfigureAwait(false);
 516→      try
 517→      {
 518→        _handleCache[documentId] = handle;
 519→        _findInProgress.Remove(documentId);
 520→
 521→        // Complete the TaskCompletionSource
 522→        if(findTask is Task<IDocHandle> task &&
 523→           task.AsyncState is TaskCompletionSource<IDocHandle> taskSource)
 524→        {
 525→          taskSource.SetResult(handle);
 526→        }
 527→      }
 528→      finally
 529→      {
 530→        _handleLock.Release();
 531→      }
 532→
 533→      // Begin lifecycle: Idle → Loading
 534→      handle.Begin();
 535→
 536→      // Split into two paths based on whether a document was loaded from storage
 537→      if(doc is not null)
 538→      {
 539→        // PATH A: Document found in storage
 540→        // Initialize the handle with the loaded document
 541→        handle.Initialize(doc, isNewDocument: false);
 542→        handle.DoneLoading();  // Loading → Ready
 543→
 544→        // Now register with subsystems
 545→        await RegisterHandle(documentId, handle).ConfigureAwait(false);
 546→
 547→        // Emit loaded event
 548→        DocumentLoaded?.Invoke(this,
 549→          new DocumentEventArgs { DocumentId = documentIdValue, Handle = handle });
 550→
 551→        return handle;  // Already ready, return immediately
 552→      }
 553→      else
 554→      {
 555→        // PATH B: Document must be loaded from network (or created if unavailable)
 556→        // Wait for network to be ready before requesting
 557→        await _network.WhenReady().ConfigureAwait(false);
 558→
 559→        // Transition to requesting state: Loading → Requesting
 560→        handle.Request();
 561→
 562→        // Now register with subsystems (synchronizer sees Requesting state)
 563→        await RegisterHandle(documentId, handle).ConfigureAwait(false);
 564→
 565→        // Wait for the handle to be ready (or timeout)
 566→        using var cts = new CancellationTokenSource(timeout.Value);
 567→        try
 568→        {
 569→          await handle.WhenReadyAsync(cts.Token).ConfigureAwait(false);
 570→          return handle;  // Document loaded successfully from network
 571→        }
 572→        catch(OperationCanceledException)
 573→        {
 574→          // Timeout: document not available from network
 575→          // Return null to indicate document doesn't exist
 576→          // Caller should use Create() to create a new document
 577→          return null;
 578→        }
 579→      }
 580→    }
 581→    catch(Exception)
 582→    {
 583→      // Clean up on error
 584→      await _handleLock.WaitAsync().ConfigureAwait(false);
 585→      try
 586→      {
 587→        _findInProgress.Remove(documentId);
 588→      }
 589→      finally
 590→      {
 591→        _handleLock.Release();
 592→      }
 593→
 594→      throw;
 595→    }
 596→  }
 597→
 598→  #endregion
 599→
 600→  #region Document Lifecycle - Delete, Clone, Import, Export
 601→
 602→  /// <summary>
 603→  /// Deletes a document from the repository.
 604→  /// </summary>
 605→  /// <param name="documentId">The document ID to delete.</param>
 606→  public async Task Delete(string documentId)
 607→  {
 608→    if(string.IsNullOrWhiteSpace(documentId))
 609→      throw new ArgumentException("Document ID cannot be null or whitespace", nameof(documentId));
 610→
 611→    ThrowIfDisposed();
 612→
 613→    IDocHandle? handle;
 614→
 615→    await _handleLock.WaitAsync().ConfigureAwait(false);
 616→    try
 617→    {
 618→      if(!_handleCache.TryGetValue(documentId, out handle))
 619→      {
 620→        return;
 621→      }
 622→
 623→      _handleCache.Remove(documentId);
 624→    }
 625→    finally
 626→    {
 627→      _handleLock.Release();
 628→    }
 629→
 630→    // Unregister from subsystems
 631→    await _synchronizer.RemoveDocument(documentId).ConfigureAwait(false);
 632→
 633→    // Mark handle as deleted
 634→    handle.Delete();
 635→
 636→    // Emit event
 637→    DocumentDeleted?.Invoke(this, new DocumentDeletedEventArgs { DocumentId = handle.DocumentId });
 638→
 639→    // Fire-and-forget storage deletion to maintain sync API
 640→    if(_storage is not null)
 641→    {
 642→      _ = Task.Run(async () =>
 643→      {
 644→        try
 645→        {
 646→          await _storage.RemoveDoc(documentId).ConfigureAwait(false);
 647→        }
 648→        catch(Exception ex)
 649→        {
 650→          // Log but don't throw - storage deletion shouldn't block document deletion
 651→          // In production, use proper logging
 652→          System.Diagnostics.Debug.WriteLine($"Failed to delete document from storage: {ex}");
 653→        }
 654→      });
 655→    }
 656→  }
 657→
 658→  /// <summary>
 659→  /// Creates a new document as a clone of an existing document.
 660→  /// </summary>
 661→  /// <typeparam name="T">The document content type.</typeparam>
 662→  /// <param name="source">The source handle to clone.</param>
 663→  /// <returns>A task that resolves to a handle to the cloned document.</returns>
 664→  public async Task<DocHandle<T>> Clone<T>(DocHandle<T> source)
 665→  {
 666→    if(source is null)
 667→      throw new ArgumentNullException(nameof(source));
 668→
 669→    ThrowIfDisposed();
 670→
 671→    // Generate new document ID
 672→    var newDocumentId = _idFactory is not null
 673→      ? DocumentId.FromBinary(await _idFactory(Array.Empty<string>()).ConfigureAwait(false))
 674→      : DocumentId.Generate();
 675→
 676→    // Clone the underlying document
 677→    var sourceDocHandle = source;
 678→    var sourceDoc = sourceDocHandle.Doc();
 679→    var clonedDocBytes = (sourceDoc as AutomergeDocument)!.Save();
 680→    var clonedDoc = AutomergeDocument.Load(clonedDocBytes);
 681→
 682→    // Create new handle
 683→    var handle = new DocHandle<T>(
 684→      newDocumentId,
 685→      new DocHandleOptions<T> { IsNew = true, ViewFactory = CreateViewFactory<T>() },
 686→      clonedDoc);
 687→
 688→    await _handleLock.WaitAsync().ConfigureAwait(false);
 689→    try
 690→    {
 691→      _handleCache[newDocumentId] = handle;
 692→    }
 693→    finally
 694→    {
 695→      _handleLock.Release();
 696→    }
 697→
 698→    // Register outside the lock to prevent deadlocks
 699→    await RegisterHandle(newDocumentId, handle).ConfigureAwait(false);
 700→
 701→    // Emit event
 702→    DocumentLoaded?.Invoke(this,
 703→      new DocumentEventArgs { DocumentId = newDocumentId, Handle = handle });
 704→
 705→    return handle;
 706→  }
 707→
 708→  /// <summary>
 709→  /// Exports a document as binary data.
 710→  /// </summary>
 711→  /// <param name="documentId">The document ID to export.</param>
 712→  /// <returns>The binary representation of the document, or null if not found.</returns>
 713→  public async Task<byte[]?> Export(string documentId)
 714→  {
 715→    if(string.IsNullOrWhiteSpace(documentId))
 716→      throw new ArgumentException("Document ID cannot be null or whitespace", nameof(documentId));
 717→
 718→    ThrowIfDisposed();
 719→
 720→    // Try to get from cache first
 721→    await _handleLock.WaitAsync().ConfigureAwait(false);
 722→    IDocHandle? handle;
 723→    try
 724→    {
 725→      if(!_handleCache.TryGetValue(documentId, out handle))
 726→      {
 727→        // Not in cache, try loading from storage
 728→        if(_storage is not null)
 729→        {
 730→          var doc = await _storage.LoadDoc(documentId).ConfigureAwait(false);
 731→          if(doc is not null)
 732→          {
 733→            return doc.Save();
 734→          }
 735→        }
 736→
 737→        return null;
 738→      }
 739→    }
 740→    finally
 741→    {
 742→      _handleLock.Release();
 743→    }
 744→
 745→    // Export from handle
 746→    var document = handle.GetDocument();
 747→    return document!.Save();
 748→  }
