 750→  /// <summary>
 751→  /// Imports a document from binary data.
 752→  /// </summary>
 753→  /// <typeparam name="T">The document content type.</typeparam>
 754→  /// <param name="data">The binary data to import.</param>
 755→  /// <param name="documentId">Optional document ID. If null, a new ID is generated.</param>
 756→  /// <returns>A task that resolves to a handle to the imported document.</returns>
 757→  public async Task<DocHandle<T>> Import<T>(byte[] data, string? documentId = null)
 758→  {
 759→    if(data is null || data.Length == 0)
 760→      throw new ArgumentException("Data cannot be null or empty", nameof(data));
 761→
 762→    ThrowIfDisposed();
 763→
 764→    // Load document from binary
 765→    var doc = AutomergeDocument.Load(data);
 766→
 767→    // Generate or validate document ID
 768→    if(documentId is null)
 769→    {
 770→      // Extract ID from document heads
 771→      var heads = doc.GetHeads();
 772→      documentId = _idFactory is not null
 773→        ? DocumentId.FromBinary(await _idFactory(heads).ConfigureAwait(false))
 774→        : DocumentId.Generate();
 775→    }
 776→    else if(!DocumentId.IsValid(documentId))
 777→    {
 778→      throw new ArgumentException($"Invalid document ID: {documentId}", nameof(documentId));
 779→    }
 780→
 781→    // Create handle
 782→    var handle = new DocHandle<T>(
 783→      documentId,
 784→      new DocHandleOptions<T> { IsNew = false, ViewFactory = CreateViewFactory<T>() },
 785→      doc);
 786→
 787→    await _handleLock.WaitAsync().ConfigureAwait(false);
 788→    try
 789→    {
 790→      // Check if already exists
 791→      if(_handleCache.ContainsKey(documentId))
 792→      {
 793→        throw new InvalidOperationException($"Document already exists: {documentId}");
 794→      }
 795→
 796→      _handleCache[documentId] = handle;
 797→    }
 798→    finally
 799→    {
 800→      _handleLock.Release();
 801→    }
 802→
 803→    // Register outside the lock to prevent deadlocks
 804→    await RegisterHandle(documentId, handle).ConfigureAwait(false);
 805→
 806→    // Emit event
 807→    DocumentLoaded?.Invoke(this,
 808→      new DocumentEventArgs { DocumentId = DocumentId.Parse(documentId), Handle = handle });
 809→
 810→    return handle;
 811→  }
