1054→  /// <summary>
1055→  /// Callback for synchronizer to get document.
1056→  /// Uses synchronous Wait() because this is passed as a sync delegate to the synchronizer.
1057→  /// The lock is only held briefly for dictionary lookup after restructuring all public methods
1058→  /// to release the lock before calling RegisterHandle.
1059→  /// </summary>
1060→  AutomergeDocument? GetDocument(string documentId)
1061→  {
1062→    _handleLock.Wait();
