1078→  /// <summary>
1079→  /// Callback for synchronizer to update document.
1080→  /// Uses synchronous Wait() because this is passed as a sync delegate to the synchronizer.
1081→  /// The lock is only held briefly for dictionary lookup after restructuring all public methods
1082→  /// to release the lock before calling RegisterHandle.
1083→  /// </summary>
1084→  void UpdateDocument(string documentId, AutomergeDocument document)
1085→  {
1086→    _handleLock.Wait();
1087→    IDocHandle? handle;
1088→    bool isNewHandle = false;
1089→    try
1090→    {
1091→      if(!_handleCache.TryGetValue(documentId, out handle))
1092→      {
1093→        // Document received from sync but no handle exists yet.
1094→        // This happens when a peer sends sync data for a document the server hasn't seen.
1095→        // RequestDocument runs Find() in Task.Run (async), so the handle may not be cached yet.
1096→        // Create a handle now to prevent the synced data from being silently discarded.
1097→        var newHandle = new DocHandle<object>(
1098→          documentId,
1099→          new DocHandleOptions<object>
1100→          {
1101→            IsNew = false,
1102→            ViewFactory = CreateViewFactory<object>()
1103→          },
1104→          document: null);
1105→
1106→        _handleCache[documentId] = newHandle;
1107→        handle = newHandle;
1108→        isNewHandle = true;
1109→      }
1110→    }
1111→    finally
1112→    {
1113→      _handleLock.Release();
1114→    }
1115→
1116→    if(isNewHandle)
1117→    {
1118→      // New handle discovered via sync — initialize lifecycle: Idle → Loading → Ready
1119→      handle.Begin();
1120→      handle.Initialize(document, isNewDocument: false);
1121→      handle.DoneLoading();
1122→
1123→      // Wire up events for persistence and synchronizer notifications.
1124→      // RegisterHandle is async; fire-and-forget since this callback is synchronous.
1125→      _ = Task.Run(async () =>
1126→      {
1127→        try
1128→        {
1129→          await RegisterHandle(documentId, (DocHandle<object>)handle).ConfigureAwait(false);
1130→
1131→          DocumentLoaded?.Invoke(this, new DocumentEventArgs
1132→          {
1133→            DocumentId = DocumentId.Parse(documentId),
1134→            Handle = handle
1135→          });
1136→        }
1137→        catch(Exception)
1138→        {
1139→          // Intentionally swallowed: sync-discovered handle registration
1140→          // failures should not break the sync flow.
1141→        }
1142→      });
1143→    }
1144→    else if(handle.State == HandleState.Requesting || handle.State == HandleState.Loading)
1145→    {
1146→      // Handle exists but waiting for data — initialize with received document
1147→      handle.Initialize(document, isNewDocument: false);
1148→      handle.DoneLoading();  // Transition to Ready
1149→    }
1150→    else if(handle.State == HandleState.Ready)
1151→    {
1152→      // Handle already initialized — notify about remote change (triggers HeadsChanged → save)
1153→      handle.NotifyRemoteChange(document);
1154→    }
1155→  }
