1202→  /// <summary>
1203→  /// Flushes pending saves for specified documents (or all documents).
1204→  /// </summary>
1205→  /// <param name="documentIds">Optional list of document IDs to flush. If null, flushes all.</param>
1206→  public async Task Flush(IEnumerable<string>? documentIds = null)
1207→  {
1208→    if(_storage is null) return;
1209→
1210→    ThrowIfDisposed();
1211→
1212→    var idsToFlush = documentIds?.ToList() ?? _handleCache.Keys.ToList();
1213→
1214→    var saveTasks = new List<Task>();
1215→
1216→    foreach(var documentId in idsToFlush)
1217→    {
1218→      // Cancel pending throttled save
1219→      await _saveLock.WaitAsync().ConfigureAwait(false);
1220→      try
1221→      {
1222→        if(_pendingSaves.TryGetValue(documentId, out var cts))
1223→        {
1224→          cts.Cancel();
1225→          _pendingSaves.Remove(documentId);
1226→        }
1227→      }
1228→      finally
1229→      {
1230→        _saveLock.Release();
1231→      }
1232→
1233→      // Perform immediate save
1234→      saveTasks.Add(PerformSave(documentId));
1235→    }
1236→
1237→    await Task.WhenAll(saveTasks).ConfigureAwait(false);
1238→  }
