343→  /// <summary>
344→  /// Applies a full document snapshot from a peer.
345→  /// </summary>
346→  private void ReceiveDocumentSnapshot(DocumentSnapshotMessage message, PeerId senderId)
347→  {
348→    var doc = AutomergeDocument.Load(message.Data);
349→    _updateDocument(doc);
350→    _peerStatuses[senderId] = PeerDocumentStatus.Has;
351→
352→    if(_syncStates.TryGetValue(senderId, out var existingState))
353→    {
354→      existingState.Dispose();
355→    }
356→
357→    _syncStates[senderId] = AutomergeSyncState.Create();
358→  }
