360→  /// <summary>
361→  /// Generates and sends a sync message to a peer.
362→  /// If we don't have the document, sends a RequestMessage instead.
363→  /// </summary>
364→  private void SendSyncMessage(PeerId peerId, List<Action> deferredEvents)
365→  {
366→    // Get document
367→    var doc = _getDocument();
368→    if(doc is null)
369→    {
370→      // We don't have the document - send a RequestMessage to request it from the peer
371→      // Create an empty sync state to generate the initial request
372→      var syncState = AutomergeSyncState.Create();
373→      var emptyDoc = AutomergeDocument.Create();
374→      var requestData = emptyDoc.GenerateSyncMessage(syncState);
375→
376→      // Dispose temporary objects
377→      syncState.Dispose();
378→
379→      // Create and defer sending the request message
380→      var requestMessage = new RequestMessage
381→      {
382→        DocumentId = _documentIdValue,
383→        Data = requestData ?? Array.Empty<byte>()
384→      };
385→
386→      _messagesSent++;
387→      var requestArgs = new SyncMessageEventArgs
388→      {
389→        DocumentId = _documentIdValue,
390→        TargetPeerId = peerId,
391→        Message = requestMessage
392→      };
393→      deferredEvents.Add(() => MessageToSend?.Invoke(this, requestArgs));
394→
395→      // Defer metrics (not complete - we're requesting)
396→      var metricsArgs = new SyncMetricsEventArgs
397→      {
398→        DocumentId = _documentIdValue,
399→        PeerId = peerId,
400→        MessagesSent = _messagesSent,
401→        MessagesReceived = _messagesReceived,
402→        IsComplete = false
403→      };
404→      deferredEvents.Add(() => MetricsUpdated?.Invoke(this, metricsArgs));
405→      return;
406→    }
407→
408→    // Get sync state for this peer
409→    var peerSyncState = GetOrCreateSyncState(peerId);
410→
411→    byte[]? messageData;
412→    var docLock = _getDocumentLock();
413→    docLock?.Wait();
414→    try
415→    {
416→      messageData = doc.GenerateSyncMessage(peerSyncState);
417→    }
418→    finally
419→    {
420→      docLock?.Release();
421→    }
422→
423→    if(messageData is null || messageData.Length == 0)
424→    {
425→      var peerStatus = _peerStatuses.TryGetValue(peerId, out var status)
426→        ? status
427→        : PeerDocumentStatus.Unknown;
428→
429→      if(peerStatus != PeerDocumentStatus.Has)
430→      {
431→        docLock = _getDocumentLock();
432→        docLock?.Wait();
433→        byte[] snapshotData;
434→        try
435→        {
436→          snapshotData = doc.Save();
437→        }
438→        finally
439→        {
440→          docLock?.Release();
441→        }
442→        var snapshotMessage = new DocumentSnapshotMessage
443→        {
444→          DocumentId = _documentIdValue,
445→          Data = snapshotData
446→        };
447→
448→        if(_syncStates.TryGetValue(peerId, out var existingState))
449→        {
450→          existingState.Dispose();
451→        }
452→
453→        _syncStates[peerId] = AutomergeSyncState.Create();
454→
455→        _messagesSent++;
456→        _peerStatuses[peerId] = PeerDocumentStatus.Has;
457→
458→        var snapshotArgs = new SyncMessageEventArgs
459→        {
460→          DocumentId = _documentIdValue,
461→          TargetPeerId = peerId,
462→          Message = snapshotMessage
463→        };
464→        deferredEvents.Add(() => MessageToSend?.Invoke(this, snapshotArgs));
465→
466→        var metricsArgsSnapshot = new SyncMetricsEventArgs
467→        {
468→          DocumentId = _documentIdValue,
469→          PeerId = peerId,
470→          MessagesSent = _messagesSent,
471→          MessagesReceived = _messagesReceived,
472→          IsComplete = true
473→        };
474→        deferredEvents.Add(() => MetricsUpdated?.Invoke(this, metricsArgsSnapshot));
475→
476→        return;
477→      }
478→
479→      var metricsArgsCompleted = new SyncMetricsEventArgs
480→      {
481→        DocumentId = _documentIdValue,
482→        PeerId = peerId,
483→        MessagesSent = _messagesSent,
484→        MessagesReceived = _messagesReceived,
485→        IsComplete = true
486→      };
487→      deferredEvents.Add(() => MetricsUpdated?.Invoke(this, metricsArgsCompleted));
488→      return;
489→    }
490→
491→    var message = new SyncMessage { DocumentId = _documentIdValue, Data = messageData };
492→
493→    _messagesSent++;
494→    _peerStatuses[peerId] = PeerDocumentStatus.Has;
495→    var messageArgs = new SyncMessageEventArgs { DocumentId = _documentIdValue, TargetPeerId = peerId, Message = message };
496→    deferredEvents.Add(() => MessageToSend?.Invoke(this, messageArgs));
497→
498→    // Defer metrics (not complete if we're sending data)
499→    var metricsArgsIncomplete = new SyncMetricsEventArgs
500→    {
501→      DocumentId = _documentIdValue,
502→      PeerId = peerId,
503→      MessagesSent = _messagesSent,
504→      MessagesReceived = _messagesReceived,
505→      IsComplete = false
506→    };
507→    deferredEvents.Add(() => MetricsUpdated?.Invoke(this, metricsArgsIncomplete));
508→  }
