510→  /// <summary>
511→  /// Notifies all connected peers that the document changed locally.
512→  /// </summary>
513→  public async Task NotifyLocalChange()
514→  {
515→    ThrowIfDisposed();
516→
517→    var deferredEvents = new List<Action>();
518→
519→    await _lock.WaitAsync().ConfigureAwait(false);
520→    try
521→    {
522→      if(_activePeers.Count == 0)
523→      {
524→        return;
525→      }
526→
527→      foreach(var peer in _activePeers)
528→      {
529→        SendSyncMessage(peer, deferredEvents);
530→      }
531→    }
532→    finally
533→    {
534→      _lock.Release();
535→    }
536→
537→    foreach(var action in deferredEvents)
538→    {
539→      action();
540→    }
541→  }
