543→  /// <summary>
544→  /// Gets existing sync state for peer, or creates new one.
545→  /// </summary>
546→  private AutomergeSyncState GetOrCreateSyncState(PeerId peerId)
547→  {
548→    // Check cache first
549→    if(_syncStates.TryGetValue(peerId, out var cachedState))
550→    {
551→      return cachedState;
552→    }
553→
554→    // Create new sync state
555→    var newState = AutomergeSyncState.Create();
556→    _syncStates[peerId] = newState;
557→
558→    // Note: Storage loading is handled by CollectionSynchronizer on initialization
559→    // This method only creates in-memory state
560→
561→    return newState;
562→  }
