564→  /// <summary>
565→  /// Emits sync metrics for monitoring.
566→  /// </summary>
567→  private void EmitMetrics(PeerId peerId, bool isComplete)
568→  {
569→    MetricsUpdated?.Invoke(this,
570→      new SyncMetricsEventArgs
571→      {
572→        DocumentId = _documentIdValue,
573→        PeerId = peerId,
574→        MessagesSent = _messagesSent,
575→        MessagesReceived = _messagesReceived,
