580→  private void ThrowIfDisposed()
581→  {
582→    if(_disposed)
583→    {
584→      throw new ObjectDisposedException(nameof(DocSynchronizer));
585→    }
586→  }
587→
588→  public void Dispose()
589→  {
590→    if(_disposed) return;
591→
592→    _disposed = true;
593→
594→    _lock.Wait();
595→    try
596→    {
597→      // Dispose all sync states
598→      foreach(var state in _syncStates.Values)
599→      {
600→        state.Dispose();
601→      }
602→
603→      _syncStates.Clear();
604→      _peerStatuses.Clear();
605→      _activePeers.Clear();
606→    }
607→    finally
608→    {
609→      _lock.Release();
610→    }
611→
612→    _lock.Dispose();
613→  }
614→}
