  5→/// <summary>
  6→/// Manages synchronization for all documents in a repository.
  7→/// Routes messages to appropriate DocSynchronizers and enforces policies.
  8→/// </summary>
  9→[PublicAPI]
 10→public sealed class CollectionSynchronizer : IDisposable
 11→{
 12→  readonly Dictionary<string, DocSynchronizer> _docSynchronizers = [];
 13→  readonly HashSet<PeerId> _connectedPeers = [];
 14→  readonly SemaphoreSlim _lock = new(1, 1);
 15→  readonly ISet<string> _denylist;
 16→
 17→  Func<DocumentId, PeerId, Task<bool>>? _sharePolicy;
 18→  Func<DocumentId, PeerId, Task<bool>>? _accessPolicy;
 19→  readonly Func<string, AutomergeDocument?> _getDocument;
 20→  readonly Action<string, AutomergeDocument> _updateDocument;
 21→  readonly Func<PeerId, PeerMetadata?> _getPeerMetadata;
 22→  readonly Action<string> _requestDocument;
 23→  readonly Func<string, SemaphoreSlim?> _getDocumentLock;
 24→
 25→  bool _isDisposed;
 26→
 27→  /// <summary>
 28→  /// Event fired when a message should be sent to a peer.
 29→  /// </summary>
 30→  public event EventHandler<SyncMessageEventArgs>? MessageToSend;
 31→
 32→  /// <summary>
 33→  /// Event fired when sync state changes (for persistence).
 34→  /// </summary>
 35→  public event EventHandler<SyncStateChangedEventArgs>? SyncStateChanged;
 36→
 37→  /// <summary>
 38→  /// Event fired when sync metrics are updated.
 39→  /// </summary>
 40→  public event EventHandler<SyncMetricsEventArgs>? MetricsUpdated;
 41→
 42→  /// <summary>
 43→  /// Event fired when a document is unavailable from all peers.
 44→  /// </summary>
 45→#pragma warning disable CS0067 // Event is never used - will be used in future implementation
 46→  public event EventHandler<DocumentUnavailableEventArgs>? DocumentUnavailable;
 47→#pragma warning restore CS0067
