 49→
 50→  /// <summary>
 51→  /// Creates a new CollectionSynchronizer.
 52→  /// </summary>
 53→  /// <param name="getDocument">Callback to retrieve a document by ID</param>
 54→  /// <param name="updateDocument">Callback to update a document after receiving changes</param>
 55→  /// <param name="getPeerMetadata">Callback to retrieve peer metadata</param>
 56→  /// <param name="requestDocument">Callback to request a document (for discovery)</param>
 57→  /// <param name="getDocumentLock">Callback to retrieve the document lock for a given document ID</param>
 58→  /// <param name="denylist">Optional set of document IDs to never sync</param>
 59→  public CollectionSynchronizer(
 60→    Func<string, AutomergeDocument?> getDocument,
 61→    Action<string, AutomergeDocument> updateDocument,
 62→    Func<PeerId, PeerMetadata?> getPeerMetadata,
 63→    Action<string> requestDocument,
 64→    Func<string, SemaphoreSlim?> getDocumentLock,
 65→    ISet<string>? denylist = null)
 66→  {
 67→    _getDocument = getDocument ?? throw new ArgumentNullException(nameof(getDocument));
 68→    _updateDocument = updateDocument ?? throw new ArgumentNullException(nameof(updateDocument));
 69→    _getPeerMetadata = getPeerMetadata ?? throw new ArgumentNullException(nameof(getPeerMetadata));
 70→    _requestDocument = requestDocument ?? throw new ArgumentNullException(nameof(requestDocument));
 71→    _getDocumentLock = getDocumentLock ?? throw new ArgumentNullException(nameof(getDocumentLock));
 72→    _denylist = denylist ?? new HashSet<string>();
 73→  }
 74→
 75→
 76→  /// <summary>
 77→  /// Registers a document for synchronization with all connected peers.
 78→  /// </summary>
 79→  public async Task AddDocument(string documentId)
 80→  {
 81→    if(string.IsNullOrWhiteSpace(documentId))
 82→      throw new ArgumentException("Document ID cannot be null or whitespace", nameof(documentId));
 83→
 84→    ThrowIfDisposed();
 85→
 86→    if(IsInDenylist(documentId)) return;
 87→
 88→    // Collect deferred operations
 89→    DocSynchronizer? docSync;
 90→    var peersToSync = new List<PeerId>();
 91→
 92→    await _lock.WaitAsync().ConfigureAwait(false);
 93→    try
 94→    {
 95→      docSync = GetOrCreateDocSync(documentId);
 96→
 97→      // Collect peers to sync with
 98→      foreach(var peer in _connectedPeers)
 99→      {
100→        if(await ShouldShare(documentId, peer).ConfigureAwait(false))
101→        {
102→          peersToSync.Add(peer);
103→        }
104→      }
105→    }
106→    finally
107→    {
108→      _lock.Release();
109→    }
110→
111→    // Begin syncing outside the lock to prevent deadlocks
112→    foreach(var peer in peersToSync)
113→    {
114→      await docSync.BeginSync(peer).ConfigureAwait(false);
115→    }
116→  }
117→
118→  /// <summary>
119→  /// Unregisters a document from synchronization.
120→  /// </summary>
121→  public async Task RemoveDocument(string documentId)
122→  {
123→    ThrowIfDisposed();
124→
125→    await _lock.WaitAsync().ConfigureAwait(false);
126→    try
127→    {
128→      if(_docSynchronizers.TryGetValue(documentId, out var docSync))
129→      {
130→        docSync.Dispose();
131→        _docSynchronizers.Remove(documentId);
132→      }
133→    }
134→    finally
135→    {
136→      _lock.Release();
137→    }
138→  }
