140→  /// <summary>
141→  /// Called when a new peer connects. Begins syncing all documents with this peer.
142→  /// </summary>
143→  public async Task OnPeerConnected(PeerId peerId)
144→  {
145→    ThrowIfDisposed();
146→
147→    // Collect deferred operations
148→    var docsToSync = new List<(string documentId, DocSynchronizer docSync)>();
149→
150→    await _lock.WaitAsync().ConfigureAwait(false);
151→    try
152→    {
153→      if(_connectedPeers.Contains(peerId)) return;
154→
155→      _connectedPeers.Add(peerId);
156→
157→      // Collect documents to sync with this peer
158→      foreach(var (documentId, docSync) in _docSynchronizers)
159→      {
160→        if(await ShouldShare(documentId, peerId).ConfigureAwait(false))
161→        {
162→          docsToSync.Add((documentId, docSync));
163→        }
164→      }
165→    }
166→    finally
167→    {
168→      _lock.Release();
169→    }
170→
171→    // Begin syncing outside the lock to prevent deadlocks
172→    foreach(var (documentId, docSync) in docsToSync)
173→    {
174→      await docSync.BeginSync(peerId).ConfigureAwait(false);
175→    }
176→  }
177→
178→  /// <summary>
179→  /// Called when a peer disconnects. Cleans up sync state for this peer.
180→  /// </summary>
181→  public async Task OnPeerDisconnected(PeerId peerId)
182→  {
183→    ThrowIfDisposed();
184→
185→    await _lock.WaitAsync().ConfigureAwait(false);
186→    try
187→    {
188→      _connectedPeers.Remove(peerId);
189→
190→      // End sync for all documents
191→      foreach(var docSync in _docSynchronizers.Values)
192→      {
193→        await docSync.EndSync(peerId).ConfigureAwait(false);
194→      }
195→    }
196→    finally
197→    {
198→      _lock.Release();
199→    }
200→  }
