202→  /// <summary>
203→  /// Routes incoming message to appropriate DocSynchronizer.
204→  /// Handles document discovery for unknown documents.
205→  /// </summary>
206→  public async Task OnMessageReceived(IRepoMessage message)
207→  {
208→    ThrowIfDisposed();
209→
210→    if(message is null) return;
211→    if(message.SenderId is null) return; // Must have sender
212→    var documentIdValue = message.DocumentId?.Value;
213→    if(documentIdValue is null) return; // Must have document ID
214→
215→    var documentId = documentIdValue;
216→    var senderId = message.SenderId.Value;
217→
218→    // Check denylist
219→    if(IsInDenylist(documentId)) return;
220→
221→    // Check access policy
222→    if(!await CanAccess(documentId, senderId).ConfigureAwait(false))
223→    {
224→      // Access denied, don't process message
225→      return;
226→    }
227→
228→    DocSynchronizer? docSync;
229→    bool needsBeginSync = false;
230→
231→    await _lock.WaitAsync().ConfigureAwait(false);
232→    try
233→    {
234→      // Get or create doc synchronizer
235→      docSync = GetOrCreateDocSync(documentId);
236→
237→      // If this is a new document we discovered, request it
238→      var doc = _getDocument(documentId);
239→      if(doc is null && !await docSync.HasPeer(senderId).ConfigureAwait(false))
240→      {
241→        // We don't have this document, trigger discovery
242→        _requestDocument(documentId);
243→      }
244→
245→      // Check if peer needs to be tracked
246→      if(!await docSync.HasPeer(senderId).ConfigureAwait(false))
247→      {
248→        needsBeginSync = true;
249→      }
250→    }
251→    finally
252→    {
253→      _lock.Release();
254→    }
255→
256→    // Begin sync outside the lock to prevent deadlocks
257→    if(needsBeginSync)
258→    {
259→      await docSync.BeginSync(senderId).ConfigureAwait(false);
260→    }
261→
262→    // Process message (outside lock to prevent deadlocks)
263→    await docSync.ReceiveMessage(message, senderId).ConfigureAwait(false);
264→  }
265→
266→  /// <summary>
267→  /// Notifies the synchronizer that a local document change occurred.
268→  /// </summary>
269→  /// <param name="documentId">The document identifier.</param>
270→  public async Task NotifyDocumentChanged(string documentId)
271→  {
272→    ThrowIfDisposed();
273→
274→    DocSynchronizer? docSync;
275→
276→    await _lock.WaitAsync().ConfigureAwait(false);
277→    try
278→    {
279→      if(!_docSynchronizers.TryGetValue(documentId, out docSync))
280→      {
281→        return;
282→      }
283→    }
284→    finally
285→    {
286→      _lock.Release();
287→    }
288→
289→    await docSync.NotifyLocalChange().ConfigureAwait(false);
290→  }
