292→  /// <summary>
293→  /// Sets the share policy (which documents to proactively share with which peers).
294→  /// </summary>
295→  public void SetSharePolicy(Func<DocumentId, PeerId, Task<bool>> policy)
296→  {
297→    _sharePolicy = policy;
298→  }
299→
300→  /// <summary>
301→  /// Sets the access policy (which peers can access which documents).
302→  /// </summary>
303→  public void SetAccessPolicy(Func<DocumentId, PeerId, Task<bool>> policy)
304→  {
305→    _accessPolicy = policy;
306→  }
307→
308→  /// <summary>
309→  /// Gets existing DocSynchronizer or creates new one.
310→  /// Wires up events on creation.
311→  /// </summary>
312→  private DocSynchronizer GetOrCreateDocSync(string documentId)
313→  {
314→    if(_docSynchronizers.TryGetValue(documentId, out var existing))
315→    {
316→      return existing;
317→    }
318→
319→    // Create new doc synchronizer
320→    var docSync = new DocSynchronizer(
321→      documentId,
322→      () => _getDocument(documentId),
323→      updatedDoc => _updateDocument(documentId, updatedDoc),
324→      _getPeerMetadata,
325→      () => _getDocumentLock(documentId));
326→
327→    // Wire up events
328→    docSync.MessageToSend += (sender, args) => MessageToSend?.Invoke(this, args);
329→    docSync.SyncStateChanged += (sender, args) => SyncStateChanged?.Invoke(this, args);
330→    docSync.MetricsUpdated += (sender, args) => MetricsUpdated?.Invoke(this, args);
331→
332→    _docSynchronizers[documentId] = docSync;
333→    return docSync;
334→  }
335→
336→  /// <summary>
337→  /// Checks if document should be proactively shared with peer.
338→  /// Default: share all documents.
339→  /// </summary>
340→  private async Task<bool> ShouldShare(string documentId, PeerId peerId)
341→  {
342→    if(_sharePolicy is null) return true;
343→
344→    try
345→    {
346→      var docId = DocumentId.Parse(documentId);
347→      return await _sharePolicy(docId, peerId).ConfigureAwait(false);
348→    }
349→    catch
350→    {
351→      // Policy failure, default to not sharing
352→      return false;
353→    }
354→  }
355→
356→  /// <summary>
357→  /// Checks if peer can access document.
358→  /// Default: allow all access.
359→  /// </summary>
360→  private async Task<bool> CanAccess(string documentId, PeerId peerId)
361→  {
362→    if(_accessPolicy is null) return true;
363→
364→    try
365→    {
366→      var docId = DocumentId.Parse(documentId);
367→      return await _accessPolicy(docId, peerId).ConfigureAwait(false);
368→    }
369→    catch
370→    {
371→      // Policy failure, default to denying access
372→      return false;
373→    }
374→  }
375→
376→  /// <summary>
377→  /// Checks if document is in denylist.
378→  /// </summary>
379→  private bool IsInDenylist(string documentId)
380→  {
381→    return _denylist.Contains(documentId);
382→  }
383→
384→  private void ThrowIfDisposed()
385→  {
386→    if(_isDisposed)
387→    {
388→      throw new ObjectDisposedException(nameof(CollectionSynchronizer));
389→    }
390→  }
391→
392→  public void Dispose()
393→  {
394→    if(_isDisposed) return;
395→
396→    _isDisposed = true;
397→
398→    _lock.Wait();
399→    try
400→    {
401→      // Dispose all doc synchronizers
402→      foreach(var docSync in _docSynchronizers.Values)
403→      {
404→        docSync.Dispose();
405→      }
406→
407→      _docSynchronizers.Clear();
408→      _connectedPeers.Clear();
409→    }
410→    finally
411→    {
412→      _lock.Release();
413→    }
414→
415→    _lock.Dispose();
416→  }
417→}
