316→  public DocHandle<T> View(IReadOnlyList<string> heads)
317→  {
318→    if(heads is null)
319→      throw new ArgumentNullException(nameof(heads));
320→
321→    if(heads.Count == 0)
322→      throw new ArgumentException("Heads cannot be empty.", nameof(heads));
323→
324→    EnsureReady();
325→
326→    // Clone the document by saving and loading
327→    var documentData = ReadAsync(doc => doc.Save()).GetAwaiter().GetResult();
328→    var clonedDoc = AutomergeDocument.Load(documentData);
329→
330→    // Isolate the clone to the specified heads
331→    clonedDoc.Isolate(heads);
332→
333→    // Create a new read-only handle with fixed heads
334→    var viewHandle = new DocHandle<T>(
335→      DocumentId,
336→      new DocHandleOptions<T>
337→      {
338→        IsNew = false,
339→        Heads = heads,
340→        Timeout = _timeout,
341→        ViewFactory = _viewFactory
342→      },
343→      clonedDoc);
344→
345→    return viewHandle;
