400→  public DocLocalChange<T>? Change(
401→    Action<AutomergeDocument> mutation,
402→    string? message = null,
403→    long? timestampMillis = null,
404→    CancellationToken cancellationToken = default) =>
405→    ChangeAsync(mutation, message, timestampMillis, cancellationToken).GetAwaiter().GetResult();
