407→  public async ValueTask<DocLocalChange<T>?> ChangeAsync(
408→    Action<AutomergeDocument> mutation,
409→    string? message = null,
410→    long? timestampMillis = null,
411→    CancellationToken cancellationToken = default)
412→  {
413→    ArgumentNullException.ThrowIfNull(mutation);
414→
415→    // Check if we need to initialize the document (virtual document pattern)
416→    AutomergeDocument document;
417→    var existingDoc = Volatile.Read(ref _document);
418→    if(existingDoc is null)
419→    {
420→      // Document doesn't exist yet - create it (handles the case where Find() timed out)
421→      lock(_stateGate)
422→      {
423→        if(_state == HandleState.Loading || _state == HandleState.Requesting)
424→        {
425→          var newDoc = AutomergeDocument.Create();
426→          Initialize(newDoc, isNewDocument: true);
427→          DoneLoading();
428→        }
429→      }
430→      document = await WaitForDocumentAsync(cancellationToken).ConfigureAwait(false);
431→    }
432→    else
433→    {
434→      document = existingDoc;
435→    }
436→
437→    EnsureEditable();
438→
439→    DocLocalChange<T>? change;
440→    await _documentLock.WaitAsync(cancellationToken).ConfigureAwait(false);
441→    try
442→    {
443→      EnsureEditable();
444→      mutation(document);
445→      var changeHash = document.Commit(message, timestampMillis);
446→      UpdateCachedHeads(document.GetHeads());
447→
448→      if(changeHash is null)
449→      {
450→        return null;
451→      }
452→
453→      var lastChange = document.GetLastLocalChange();
454→      if(lastChange is null)
455→      {
456→        return null;
457→      }
458→
459→      var clonedChange = lastChange.ToArray();
460→      _pendingLocalChanges.Add(clonedChange);
461→      var readOnlyChange = new ReadOnlyCollection<byte[]>([clonedChange]);
462→      change = new DocLocalChange<T>(this, changeHash, readOnlyChange);
463→    }
464→    finally
465→    {
466→      _documentLock.Release();
467→    }
468→
469→    OnChanged(change, isLocal: true, null);
470→    return change;
471→  }
