473→  /// <summary>
474→  /// Makes a change to the document as if it were at the specified heads, creating a concurrent branch.
475→  /// </summary>
476→  /// <param name="heads">The heads to fork at before making the change.</param>
477→  /// <param name="mutation">The mutation to apply to the forked document.</param>
478→  /// <returns>
479→  /// A list of binary changes representing the concurrent change that was made.
480→  /// </returns>
481→  /// <remarks>
482→  /// <para>
483→  /// This method creates a fork of the document at the specified heads, applies the mutation,
484→  /// commits the change, and then merges the forked document back into the main document.
485→  /// This creates a concurrent branch in the document history.
486→  /// </para>
487→  /// <para>
488→  /// This is useful for reconciling external state that was modified independently from the document.
489→  /// For example, if you have a text editor that was modified while disconnected from the document,
490→  /// you can use ChangeAt to apply those changes as if they happened at the point when the editor
491→  /// last synced.
492→  /// </para>
493→  /// </remarks>
494→  /// <exception cref="ArgumentNullException">Thrown when heads or mutation is null.</exception>
495→  /// <exception cref="ArgumentException">Thrown when heads is empty.</exception>
496→  /// <exception cref="InvalidOperationException">Thrown when the document is not ready or is read-only.</exception>
497→  public IReadOnlyList<byte[]> ChangeAt(
498→    IReadOnlyList<string> heads,
499→    Action<AutomergeDocument> mutation)
500→  {
501→    if(heads is null)
502→    {
503→      throw new ArgumentNullException(nameof(heads));
504→    }
505→
506→    if(heads.Count == 0)
507→    {
508→      throw new ArgumentException("Heads cannot be empty.", nameof(heads));
509→    }
510→
511→    ArgumentNullException.ThrowIfNull(mutation);
512→    EnsureEditable();
513→
514→    return ChangeAtAsync(heads, mutation, CancellationToken.None).GetAwaiter().GetResult();
515→  }
516→
517→  async ValueTask<IReadOnlyList<byte[]>> ChangeAtAsync(
518→    IReadOnlyList<string> heads,
519→    Action<AutomergeDocument> mutation,
520→    CancellationToken cancellationToken)
521→  {
522→    var document = await WaitForDocumentAsync(cancellationToken).ConfigureAwait(false);
523→
524→    byte[]? changeBytes;
525→    await _documentLock.WaitAsync(cancellationToken).ConfigureAwait(false);
526→    try
527→    {
528→      EnsureEditable();
529→
530→      // Fork the document at the specified heads
531→      using var forkedDoc = document.ForkAtHeads(heads);
532→
533→      // Apply the mutation to the forked document
534→      mutation(forkedDoc);
535→
536→      // Commit the changes in the forked document
537→      var changeHash = forkedDoc.Commit();
538→      if(changeHash is null)
539→      {
540→        // No changes were made, return empty
541→        return Array.Empty<byte[]>();
542→      }
543→
544→      // Get the change bytes from the forked document
545→      var lastChange = forkedDoc.GetLastLocalChange();
546→      if(lastChange is null)
547→      {
548→        return Array.Empty<byte[]>();
549→      }
550→
551→      // Merge the forked document back into the main document
552→      var mergedHashes = document.Merge(forkedDoc);
553→
554→      // Update cached heads
555→      UpdateCachedHeads(document.GetHeads());
556→
557→      changeBytes = lastChange.ToArray();
558→    }
559→    finally
560→    {
561→      _documentLock.Release();
562→    }
563→
564→    // Emit change event outside lock
565→    OnChanged(null, isLocal: true, new[] { changeBytes });
566→
567→    // Return the change as a single-item list
568→    return new ReadOnlyCollection<byte[]>(new[] { changeBytes });
569→  }
570→
571→  public async ValueTask ApplyRemoteChangesAsync(
572→    IEnumerable<byte[]> changes,
573→    CancellationToken cancellationToken = default)
574→  {
575→    ArgumentNullException.ThrowIfNull(changes);
576→    EnsureReady();
577→
578→    var changeBatch = changes.Select(change => change.ToArray()).ToArray();
579→    if(changeBatch.Length == 0)
580→    {
581→      return;
582→    }
583→
584→    var document = await WaitForDocumentAsync(cancellationToken).ConfigureAwait(false);
585→
586→    await _documentLock.WaitAsync(cancellationToken).ConfigureAwait(false);
587→    try
588→    {
589→      document.ApplyChanges(changeBatch);
590→      UpdateCachedHeads(document.GetHeads());
591→    }
592→    finally
593→    {
594→      _documentLock.Release();
595→    }
596→
597→    OnChanged(null, isLocal: false, changeBatch);
598→  }
599→
600→  /// <summary>
601→  /// Notifies the handle that the document was updated externally (e.g., by sync protocol).
602→  /// Updates cached heads and triggers change events.
603→  /// </summary>
604→  public void NotifyRemoteChange(AutomergeDocument document)
605→  {
606→    EnsureNotDisposed();
607→    if(_state != HandleState.Ready)
608→    {
609→      return;
610→    }
611→
612→    _documentLock.Wait();
613→    try
614→    {
615→      UpdateCachedHeads(document.GetHeads());
616→    }
617→    finally
618→    {
619→      _documentLock.Release();
620→    }
621→
622→    OnChanged(null, isLocal: false, null);
623→  }
624→
625→  public async Task Merge(DocHandle<T> other)
626→  {
627→    if(other is null)
628→    {
629→      throw new ArgumentNullException(nameof(other));
630→    }
631→
632→    EnsureEditable();
633→
634→    bool hasChanges;
635→    await using(var mergeLock = await CompositeSemaphore.AcquireAsync(_documentLock, other._documentLock).ConfigureAwait(false))
636→    {
637→      var doc = DocInternal();
638→      var otherDoc = other.DocInternal();
639→
640→      var hashes = doc.Merge(otherDoc);
641→      hasChanges = hashes.Count > 0;
642→      if(hasChanges)
643→      {
644→        UpdateCachedHeads(doc.GetHeads());
645→      }
646→    }
647→
648→    if(hasChanges)
649→    {
650→      OnChanged(null, isLocal: true, null);
651→    }
652→  }
653→
654→  public IReadOnlyList<byte[]> DrainLocalChanges()
655→  {
656→    EnsureReady();
657→
658→    lock(_stateGate)
659→    {
660→      if(_pendingLocalChanges.Count == 0)
661→      {
662→        return Array.Empty<byte[]>();
663→      }
664→
665→      var drained = _pendingLocalChanges
666→        .Select(change => change.ToArray())
667→        .ToArray();
668→
669→      _pendingLocalChanges.Clear();
670→      return new ReadOnlyCollection<byte[]>(drained);
671→    }
672→  }
