697→  #region Internal helpers
698→
699→  AutomergeDocument DocInternal()
700→  {
701→    var document = Volatile.Read(ref _document);
702→    if(document is null)
703→    {
704→      throw new InvalidOperationException($"DocHandle '{DocumentId}' does not have an attached document.");
705→    }
706→
707→    return document;
708→  }
709→
710→  ValueTask<AutomergeDocument> WaitForDocumentAsync(CancellationToken cancellationToken)
711→  {
712→    EnsureNotDisposed();
713→
714→    var existing = Volatile.Read(ref _document);
715→    if(existing is not null)
716→    {
717→      return ValueTask.FromResult(existing);
718→    }
719→
720→    return new ValueTask<AutomergeDocument>(_readySource.Task.WaitAsync(cancellationToken));
721→  }
722→
723→  void OnChanged(DocLocalChange<T>? localChange, bool isLocal, IReadOnlyList<byte[]>? appliedChanges)
724→  {
725→    // Always fire HeadsChanged — callers only invoke OnChanged after a meaningful change
726→    // (local Change(), ApplyRemoteChanges(), NotifyRemoteChange(), or Merge()).
727→    HeadsChanged?.Invoke(this, new DocHandleHeadsChangedEventArgs<T>(this, Heads));
728→
729→    var doc = Volatile.Read(ref _document);
730→    if(doc is null)
731→    {
732→      return;
733→    }
734→
735→    Changed?.Invoke(
736→      this,
737→      new DocHandleChangeEventArgs<T>(
738→        this,
739→        _viewFactory(doc),
740→        isLocal,
741→        localChange,
742→        appliedChanges));
743→  }
744→
745→  void UpdateCachedHeads(IReadOnlyList<string> heads)
746→  {
747→    var copy = heads.Count == 0
748→      ? (IReadOnlyList<string>)Array.Empty<string>()
749→      : new ReadOnlyCollection<string>(heads.ToArray());
750→
751→    Volatile.Write(ref _currentHeads, copy);
752→  }
753→
754→  void EnsureEditable()
755→  {
756→    EnsureReady();
757→    if(IsReadOnly)
758→    {
759→      throw new InvalidOperationException("Handle is view-only and cannot be changed.");
760→    }
761→  }
762→
763→  void EnsureReady()
764→  {
765→    EnsureNotDisposed();
766→    if(!IsReady)
767→    {
768→      throw new InvalidOperationException($"DocHandle '{DocumentId}' is not ready.");
769→    }
770→  }
771→
772→  void EnsureNotDisposed()
773→  {
774→    if(Volatile.Read(ref _isDisposed))
775→    {
776→      throw new ObjectDisposedException(nameof(DocHandle<T>));
777→    }
778→  }
779→
780→  static T DefaultViewFactory(AutomergeDocument doc)
781→  {
782→    if(typeof(T) == typeof(AutomergeDocument))
783→    {
784→      return (T)(object)doc;
785→    }
786→
787→    throw new InvalidOperationException(
788→      $"Provide a view factory when constructing DocHandle<{typeof(T).Name}> so the document can be projected.");
789→  }
