793→  sealed class CompositeSemaphore : IAsyncDisposable
794→  {
795→    readonly SemaphoreSlim _first;
796→    readonly SemaphoreSlim _second;
797→
798→    CompositeSemaphore(SemaphoreSlim first, SemaphoreSlim second)
799→    {
800→      _first = first;
801→      _second = second;
802→    }
803→
804→    public static async Task<CompositeSemaphore> AcquireAsync(SemaphoreSlim first, SemaphoreSlim second)
805→    {
806→      var instance = new CompositeSemaphore(first, second);
807→      await first.WaitAsync().ConfigureAwait(false);
808→      if(!ReferenceEquals(first, second))
809→      {
810→        await second.WaitAsync().ConfigureAwait(false);
811→      }
812→
813→      return instance;
814→    }
815→
816→    public ValueTask DisposeAsync()
817→    {
818→      _second.Release();
819→      _first.Release();
820→      return ValueTask.CompletedTask;
821→    }
822→  }
823→}
