260→  void SaveCursorBeforeEdit()
261→  {
262→    if(_automergeService is null || _cursorPosition <= 0)
263→    {
264→      _savedCursor = null;
265→      return;
266→    }
267→
268→    try
269→    {
270→      ulong pos = (ulong)Math.Min(_cursorPosition, _automergeService.GetText().Length);
271→      if(pos > 0)
272→      {
273→        _savedCursor = _automergeService.GetCursor(pos - 1);
274→      }
275→      else
276→      {
277→        _savedCursor = null;
278→      }
279→    }
280→    catch(Exception)
281→    {
282→      _savedCursor = null;
283→    }
284→  }
