  7→/// <summary>
  8→/// Wraps <see cref="AutomergeDocument"/> to provide rich text CRDT operations
  9→/// for the collaborative rich text editor demo. Supports text editing, inline
 10→/// marks (bold, italic, underline, link), and block-level structure (paragraphs).
 11→/// </summary>
 12→sealed class AutomergeService : IDisposable
 13→{
 14→  readonly AutomergeDocument _document;
 15→  readonly AutomergeObjectId _textId;
 16→  readonly bool _ownsDocument;
 17→  bool _disposed;
 18→
 19→  public AutomergeService()
 20→  {
 21→    _document = AutomergeDocument.Create();
 22→    _textId = _document.PutObject(_document.RootId, "content", AutomergeContainerType.Text);
 23→    _document.Commit("Initialize text field");
 24→    _ownsDocument = true;
 25→  }
 26→
 27→  AutomergeService(AutomergeDocument document, AutomergeObjectId textId, bool ownsDocument)
 28→  {
 29→    _document = document;
 30→    _textId = textId;
 31→    _ownsDocument = ownsDocument;
 32→  }
 33→
 34→  /// <summary>
 35→  /// Gets the underlying document for sync operations.
 36→  /// </summary>
 37→  public AutomergeDocument Document => _document;
 38→
 39→  /// <summary>
 40→  /// Gets the text object identifier for direct access.
 41→  /// </summary>
 42→  public AutomergeObjectId TextId => _textId;
 43→
 44→  /// <summary>
 45→  /// Gets the current text content of the document.
 46→  /// </summary>
 47→  public string GetText()
 48→  {
 49→    ThrowIfDisposed();
 50→    return _document.GetText(_textId);
 51→  }
 52→
 53→  /// <summary>
 54→  /// Splices text at the given position: deletes <paramref name="deleteCount"/> characters
 55→  /// and inserts <paramref name="insertText"/> at <paramref name="index"/>.
 56→  /// </summary>
 57→  public void SpliceText(ulong index, long deleteCount, string insertText)
 58→  {
 59→    ThrowIfDisposed();
 60→    _document.SpliceText(_textId, index, deleteCount, insertText);
 61→    _document.Commit($"Edit at {index}");
 62→  }
 63→
 64→  /// <summary>
 65→  /// Applies or removes a bold mark on the specified range.
 66→  /// </summary>
 67→  public void MarkBold(ulong start, ulong end, bool value)
 68→  {
 69→    ThrowIfDisposed();
 70→    _document.Mark(_textId, start, end, "bold", value, ExpandMode.Both);
 71→    _document.Commit("Mark bold");
 72→  }
 73→
 74→  /// <summary>
 75→  /// Removes the bold mark from the specified range.
 76→  /// </summary>
 77→  public void UnmarkBold(ulong start, ulong end)
 78→  {
 79→    ThrowIfDisposed();
 80→    _document.Unmark(_textId, "bold", start, end, ExpandMode.Both);
 81→    _document.Commit("Unmark bold");
