143→
144→  /// <summary>
145→  /// Gets all marks applied to the text.
146→  /// </summary>
147→  public IReadOnlyList<AutomergeMarkInfo> GetMarks()
148→  {
149→    ThrowIfDisposed();
150→    return _document.GetMarks(_textId);
151→  }
152→
153→  /// <summary>
154→  /// Gets the text content segmented by marks and blocks.
155→  /// </summary>
156→  public IReadOnlyList<AutomergeSpan> GetSpans()
157→  {
158→    ThrowIfDisposed();
159→    return _document.GetSpans(_textId);
160→  }
161→
162→  /// <summary>
163→  /// Inserts a block marker at the given index, splitting the text.
164→  /// Sets the block type to <paramref name="blockType"/>.
165→  /// </summary>
166→  public void SplitBlock(ulong index, string blockType)
167→  {
168→    ThrowIfDisposed();
169→    AutomergeObjectId blockId = _document.SplitBlock(_textId, index);
170→    _document.PutString(blockId, "type", blockType);
171→    _document.Commit($"Split block at {index}");
172→  }
173→
174→  /// <summary>
175→  /// Removes a block marker at the given index, joining adjacent text.
176→  /// </summary>
177→  public void JoinBlock(ulong index)
178→  {
179→    ThrowIfDisposed();
180→    _document.JoinBlock(_textId, index);
181→    _document.Commit($"Join block at {index}");
182→  }
183→
184→  /// <summary>
185→  /// Atomically updates the span list with minimal diff.
186→  /// </summary>
187→  public void UpdateSpans(IReadOnlyList<AutomergeSpan> spans)
188→  {
189→    ThrowIfDisposed();
190→    _document.UpdateSpans(_textId, spans);
191→    _document.Commit("Update spans");
192→  }
193→
194→  /// <summary>
195→  /// Gets a stable cursor at the given index.
196→  /// </summary>
197→  public AutomergeCursor GetCursor(ulong index)
198→  {
199→    ThrowIfDisposed();
200→    return _document.GetCursor(_textId, index);
201→  }
202→
203→  /// <summary>
204→  /// Resolves a cursor to its current index position.
205→  /// </summary>
206→  public ulong GetCursorPosition(AutomergeCursor cursor)
207→  {
208→    ThrowIfDisposed();
209→    return _document.GetCursorPosition(_textId, cursor);
210→  }
211→
212→  /// <summary>
213→  /// Saves the full document state as a byte array.
214→  /// </summary>
215→  public byte[] Save()
216→  {
217→    ThrowIfDisposed();
218→    return _document.Save();
219→  }
220→
221→  /// <summary>
222→  /// Creates an AutomergeService that wraps an existing document, initializing the text field
223→  /// if it doesn't already exist. The document is NOT owned (not disposed by this service).
224→  /// </summary>
225→  public static AutomergeService FromDocument(AutomergeDocument document)
226→  {
227→    ArgumentNullException.ThrowIfNull(document);
228→
229→    var keys = document.GetKeys(document.RootId).ToList();
230→    AutomergeObjectId textId;
231→
232→    if(keys.Contains("content"))
233→    {
234→      textId = document.GetObject(document.RootId, "content")
235→        ?? throw new InvalidOperationException("Could not resolve 'content' text object.");
236→    }
237→    else
238→    {
239→      textId = document.PutObject(document.RootId, "content", AutomergeContainerType.Text);
240→      document.Commit("Initialize text field");
241→    }
242→
243→    return new AutomergeService(document, textId, ownsDocument: false);
244→  }
245→
246→  /// <summary>
247→  /// Loads a document from a previously saved byte array.
248→  /// </summary>
249→  public static AutomergeService Load(byte[] data)
250→  {
251→    AutomergeDocument doc = AutomergeDocument.Load(data);
252→    List<string> keys = doc.GetKeys(doc.RootId).ToList();
253→    if(!keys.Contains("content"))
254→    {
255→      throw new InvalidOperationException("Saved document does not contain a 'content' text field.");
256→    }
257→
258→    AutomergeObjectId textId = doc.GetObject(doc.RootId, "content")
259→      ?? throw new InvalidOperationException("Could not resolve 'content' text object.");
260→
261→    return new AutomergeService(doc, textId, ownsDocument: true);
262→  }
263→
264→  public void Dispose()
265→  {
266→    if(!_disposed)
267→    {
268→      _disposed = true;
269→      if(_ownsDocument)
270→      {
271→        _document.Dispose();
272→      }
273→    }
274→  }
275→
276→  void ThrowIfDisposed()
277→  {
278→    ObjectDisposedException.ThrowIf(_disposed, this);
279→  }
280→}
