  3→using Avalonia.Controls;
  4→using Avalonia.Threading;
  5→using DemoApp.CollaborativeEditor.Services;
  6→using DemoApp.CollaborativeEditor.ViewModels;
  7→using DemoApp.Shared;
  8→using DemoApp.Shared.Controls;
  9→using Six.Automerge;
 10→using Six.Automerge.Repository;
 11→
 12→namespace DemoApp.CollaborativeEditor.Views;
 13→
 14→public partial class EditorWindow : Window
 15→{
 16→  DocumentSessionDialogViewModel? _sessionVm;
 17→  ConnectionStatusBarViewModel? _statusBarVm;
 18→
 19→  public EditorWindow()
 20→  {
 21→    InitializeComponent();
 22→    Loaded += OnLoaded;
 23→  }
 24→
 25→  async void OnLoaded(object? sender, EventArgs e)
 26→  {
 27→    _sessionVm = new DocumentSessionDialogViewModel();
 28→    _sessionVm.ResultReady += OnSessionResultReady;
 29→
 30→    SessionDialog.DataContext = _sessionVm;
 31→    SessionDialog.RefreshRequested += OnRefreshRequested;
 32→
 33→    _statusBarVm = new ConnectionStatusBarViewModel();
 34→    StatusBar.DataContext = _statusBarVm;
 35→
 36→    // Track caret position and selection changes from the TextBox
 37→    LocalEditor.PropertyChanged += (_, args) =>
 38→    {
 39→      if(DataContext is not EditorViewModel vm)
 40→      {
 41→        return;
 42→      }
 43→
 44→      if(args.Property == TextBox.CaretIndexProperty)
 45→      {
 46→        vm.CursorPosition = LocalEditor.CaretIndex;
 47→      }
 48→
 49→      if(args.Property == TextBox.SelectionStartProperty || args.Property == TextBox.SelectionEndProperty)
 50→      {
 51→        int start = LocalEditor.SelectionStart;
 52→        int end = LocalEditor.SelectionEnd;
 53→        vm.SelectionLength = Math.Abs(end - start);
 54→      }
 55→    };
 56→
 57→    // Load stored documents, initialize connection, then fetch server documents
 58→    if(DataContext is EditorViewModel vm2 && vm2.RepoService is not null)
 59→    {
 60→      _sessionVm.LoadStoredDocuments(vm2.RepoService.StorageDirectory);
 61→      await vm2.RepoService.InitializeAsync();
 62→      WireConnectionEvents(vm2.RepoService);
 63→      await _sessionVm.LoadServerDocumentsAsync(vm2.RepoService);
 64→    }
 65→  }
 66→
 67→  async void OnRefreshRequested(object? sender, EventArgs e)
 68→  {
 69→    if(_sessionVm is null || DataContext is not EditorViewModel vm || vm.RepoService is null)
 70→    {
 71→      return;
 72→    }
 73→
 74→    await _sessionVm.LoadServerDocumentsAsync(vm.RepoService);
 75→  }
 76→
 77→  async void OnSessionResultReady(object? sender, EventArgs e)
 78→  {
 79→    if(_sessionVm?.Result is null || DataContext is not EditorViewModel vm)
 80→    {
 81→      return;
 82→    }
 83→
 84→    var result = _sessionVm.Result;
 85→    _sessionVm.IsLoading = true;
 86→    _sessionVm.ErrorMessage = null;
 87→
 88→    try
 89→    {
 90→      switch(result.Action)
 91→      {
 92→        case SessionAction.Create:
 93→          await HandleCreateAsync(vm);
 94→          break;
 95→        case SessionAction.Join:
 96→          await HandleJoinAsync(vm, result.DocumentId!);
 97→          break;
 98→        case SessionAction.Resume:
 99→          await HandleResumeAsync(vm, result.DocumentId!);
100→          break;
101→      }
102→
103→      await Dispatcher.UIThread.InvokeAsync(() => _sessionVm.IsLoading = false);
104→    }
105→    catch(OperationCanceledException)
106→    {
107→      await Dispatcher.UIThread.InvokeAsync(() =>
108→      {
109→        vm.SyncStatus = "Operation cancelled";
110→        _sessionVm.IsLoading = false;
111→      });
112→    }
113→    catch(TimeoutException)
114→    {
115→      await Dispatcher.UIThread.InvokeAsync(() =>
116→      {
117→        vm.SyncStatus = "Operation timed out";
118→        _sessionVm.ErrorMessage = "The operation timed out. The document may be unavailable or the server is not responding.";
119→        _sessionVm.IsLoading = false;
120→      });
121→    }
122→    catch(Exception ex)
123→    {
124→      await Dispatcher.UIThread.InvokeAsync(() =>
125→      {
126→        vm.SyncStatus = $"Error: {ex.Message}";
127→        _sessionVm.ErrorMessage = ex.Message;
128→        _sessionVm.IsLoading = false;
129→      });
130→    }
131→  }
132→
133→  async Task HandleCreateAsync(EditorViewModel vm)
134→  {
135→    if(vm.RepoService is null)
136→    {
137→      // Offline mode: create a standalone document
138→      var automergeService = new AutomergeService();
139→      await Dispatcher.UIThread.InvokeAsync(() => vm.SetAutomergeService(automergeService));
140→      await ShowEditorAsync(null);
141→      return;
142→    }
143→
144→    await vm.RepoService.InitializeAsync();
145→    WireConnectionEvents(vm.RepoService);
146→
147→    // Create a new document via the repo
148→    var handle = await vm.RepoService.Repo!.Create<object>();
149→
150→    // Initialize text CRDT on the document
151→    handle.Change(doc =>
152→    {
153→      doc.PutObject(doc.RootId, "content", AutomergeContainerType.Text);
154→    }, "Initialize text field");
155→
156→    var document = ((IDocHandle)handle).GetDocument()!;
157→    var automerge = AutomergeService.FromDocument(document);
158→    await Dispatcher.UIThread.InvokeAsync(() =>
159→    {
160→      vm.SetAutomergeService(automerge);
161→      vm.DocHandle = handle;
162→    });
163→
164→    await ShowEditorAsync(handle.DocumentId.ToString());
165→  }
166→
167→  async Task HandleJoinAsync(EditorViewModel vm, string documentId)
168→  {
169→    if(vm.RepoService is null)
170→    {
171→      await Dispatcher.UIThread.InvokeAsync(() =>
172→        _sessionVm!.ErrorMessage = "Cannot join: no server connection");
173→      return;
174→    }
175→
176→    await vm.RepoService.InitializeAsync();
177→    WireConnectionEvents(vm.RepoService);
178→
179→    await Dispatcher.UIThread.InvokeAsync(() => vm.SyncStatus = "Joining document...");
180→
181→    var handle = await vm.RepoService.Repo!.Find<object>(documentId, TimeSpan.FromSeconds(30));
182→    if(handle is null)
183→    {
184→      await Dispatcher.UIThread.InvokeAsync(() =>
185→        _sessionVm!.ErrorMessage = "Document not found");
186→      return;
187→    }
188→
189→    await handle.WhenReadyAsync().WaitAsync(TimeSpan.FromSeconds(30));
190→
191→    var document = ((IDocHandle)handle).GetDocument()!;
192→    var automerge = AutomergeService.FromDocument(document);
193→    await Dispatcher.UIThread.InvokeAsync(() =>
194→    {
195→      vm.SetAutomergeService(automerge);
196→      vm.DocHandle = handle;
197→    });
198→
199→    await ShowEditorAsync(handle.DocumentId.ToString());
200→  }
201→
202→  async Task HandleResumeAsync(EditorViewModel vm, string documentId)
203→  {
204→    if(vm.RepoService is null)
205→    {
206→      await Dispatcher.UIThread.InvokeAsync(() =>
207→        _sessionVm!.ErrorMessage = "Cannot resume: no server connection");
208→      return;
209→    }
210→
211→    await vm.RepoService.InitializeAsync();
212→    WireConnectionEvents(vm.RepoService);
213→
214→    await Dispatcher.UIThread.InvokeAsync(() => vm.SyncStatus = "Resuming document...");
215→
216→    // Find will load from local storage first
217→    var handle = await vm.RepoService.Repo!.Find<object>(documentId, TimeSpan.FromSeconds(10));
218→    if(handle is null)
219→    {
220→      await Dispatcher.UIThread.InvokeAsync(() =>
221→        _sessionVm!.ErrorMessage = "Document not found in storage");
222→      return;
223→    }
224→
225→    await handle.WhenReadyAsync().WaitAsync(TimeSpan.FromSeconds(30));
226→
227→    var document = ((IDocHandle)handle).GetDocument()!;
228→    var automerge = AutomergeService.FromDocument(document);
229→    await Dispatcher.UIThread.InvokeAsync(() =>
230→    {
231→      vm.SetAutomergeService(automerge);
232→      vm.DocHandle = handle;
233→    });
234→
235→    await ShowEditorAsync(handle.DocumentId.ToString());
236→  }
237→
238→  void WireConnectionEvents(RepoService repoService)
239→  {
240→    if(_statusBarVm is null)
241→    {
242→      return;
243→    }
244→
245→    _statusBarVm.PeerId = repoService.PeerId?.ToString();
246→    _statusBarVm.ServerUrl = repoService is { IsInitialized: true }
247→      ? "Connected"
248→      : "Offline";
249→
250→    // Set initial connection state (event handler below only fires on future changes)
251→    _statusBarVm.ConnectionState = repoService.ConnectionState switch
252→    {
253→      ConnectionState.Connected => DemoApp.Shared.ConnectionState.Connected,
254→      ConnectionState.Connecting => DemoApp.Shared.ConnectionState.Connecting,
255→      ConnectionState.Reconnecting => DemoApp.Shared.ConnectionState.Reconnecting,
256→      _ => DemoApp.Shared.ConnectionState.Disconnected
257→    };
258→
259→    repoService.ConnectionStateChanged += (_, state) =>
260→      Dispatcher.UIThread.Post(() =>
261→      {
262→        if(_statusBarVm is null)
263→        {
264→          return;
265→        }
266→
267→        _statusBarVm.ConnectionState = state switch
268→        {
269→          ConnectionState.Connected => DemoApp.Shared.ConnectionState.Connected,
270→          ConnectionState.Connecting => DemoApp.Shared.ConnectionState.Connecting,
271→          ConnectionState.Reconnecting => DemoApp.Shared.ConnectionState.Reconnecting,
272→          _ => DemoApp.Shared.ConnectionState.Disconnected
273→        };
274→      });
275→
276→    repoService.PeerCountChanged += (_, count) =>
277→      Dispatcher.UIThread.Post(() =>
278→      {
279→        if(_statusBarVm is not null)
280→        {
281→          _statusBarVm.PeerCount = count;
282→        }
283→      });
284→  }
285→
286→  async Task ShowEditorAsync(string? documentId)
287→  {
288→    await Dispatcher.UIThread.InvokeAsync(() =>
289→    {
290→      SessionPanel.IsVisible = false;
291→      EditorPanel.IsVisible = true;
292→
293→      if(_statusBarVm is not null)
294→      {
295→        _statusBarVm.DocumentId = documentId ?? "local";
296→      }
297→
298→      LocalEditor.Focus();
299→    });
300→  }
301→}
