    OnPropertyChanged(nameof(CanJoin));  // Enable Join button when ID entered
  }
}

public bool CanJoin => !string.IsNullOrWhiteSpace(_joinDocumentId) && !_isLoading;

public void Join()
{
  if(!CanJoin) return;

  Result = new SessionResult
  {
    Action = SessionAction.Join,
    DocumentId = _joinDocumentId.Trim()
  };
  ResultReady?.Invoke(this, EventArgs.Empty);
}
```

### Document Lists:

- **StoredDocuments** — Scanned from local storage (FileSystemStorageAdapter sharded dirs)
- **ServerDocuments** — Fetched from server via `RepoService.ListServerDocumentsAsync()`
- **AllDocuments** — Merged list with `DocumentSource` enum (Local, Server, or Both)

**UI Actions:**
- "Create New" button → `SessionAction.Create`
- "Join" button → `SessionAction.Join` (requires manual ID entry)
- Resume buttons → `SessionAction.Resume` (pre-filled IDs from stored/server lists)

---

## Key Architectural Insights

1. **4 replicas** auto-start by default (unlike TextEditor with 2 replicas)
2. **MCP Connector** wired in DEBUG mode only via `AddAvaloniaMcpConnector()`
3. **`_isRemoteUpdate` guard pattern** prevents recursive local edits when processing remote changes
4. **Cursor preservation** across merges using `AutomergeCursor` API
5. **Three session types**: Create (new doc), Join (by ID), Resume (from local + sync)
6. **Hybrid storage**: Local filesystem + server sync with graceful offline fallback

All file paths are absolute and ready for further exploration.

